mapper.select:
SELECT A.PRODUCT_ID, A.TITLE, (SELECT IMAGE_URL FROM tb_product_image WHERE PRODUCT_ID = A.PRODUCT_ID AND REPRESENT = 1 LIMIT 1) AS IMAGE_URL, O.ORDER_ID, O.ORDER_NO, O.USER_NO, O.ORDER_STATUS, O.BRANCH_DEPOSIT_STATUS, O.TOTAL_ITEM_AMOUNT, O.DELIVERY_FEE, O.DISCOUNT_AMOUNT, O.TOTAL_PAY_AMOUNT, DATE_FORMAT(O.ORDERED_AT, '%Y.%m.%d %H:%i') AS ORDERED_AT, O.PAID_AT, O.DELIVERY_COMPANY_CODE, O.DELIVERED_AT, (SELECT CODE_NM FROM op_code WHERE GROUP_ID = 'R010660' AND CODE = O.DELIVERY_COMPANY_CODE) AS DELIVERY_COMPANY_NM, (SELECT CODE_NM FROM op_code WHERE GROUP_ID = 'R010650' AND CODE = O.ORDER_STATUS) AS ORDER_STATUS_NM, O.TRACKING_NO, I.PRODUCT_NAME, I.UNIT_PRICE, I.QUANTITY, B.BRANCH_NAME FROM tb_product A INNER JOIN tb_order_items I ON A.PRODUCT_ID = I.PRODUCT_ID INNER JOIN tb_orders O ON I.ORDER_ID = O.ORDER_ID LEFT JOIN tb_branches B ON O.BRANCH_ID = B.BRANCH_ID
1=1 AND O.ORDER_STATUS != '10'
AND O.BRANCH_ID = #{branchId}
AND O.ORDER_STATUS = #{orderStatus}
AND O.ORDERED_AT >= STR_TO_DATE(#{orderStDt}, '%Y-%m-%d')
AND O.ORDERED_AT < DATE_ADD(STR_TO_DATE(#{orderEdDt}, '%Y-%m-%d'), INTERVAL 1 DAY)
AND (O.ORDER_NO LIKE CONCAT('%', #{searchKeyword}, '%') OR B.BRANCH_NAME LIKE CONCAT('%', #{searchKeyword}, '%'))
ORDER BY O.ORDERED_AT DESC LIMIT #{limit} OFFSET #{offset}
